CommonData.PCCustomCSS:
/* Main Container */
#onetrust-pc-sdk {
  font-family: "AvenirNext forINTUIT", "Avenir", "Arial" !important;
  min-width: 650px !important;
  height: 70% !important;
  border-radius: 10px !important;
}

/* LOGO */
#onetrust-pc-sdk .pc-logo img,
#onetrust-pc-sdk .ot-pc-logo img {
  max-height: 92%;
  max-width: 92%;
}


/* Title */
#onetrust-pc-sdk #ot-pc-title {
  font-size: 20px !important;
  font-weight: 600 !important;
  margin-top: 24px !important;
}

#onetrust-pc-sdk .ot-optout-signal {
  display: none !important;
}

/* Title Description */
#onetrust-pc-sdk #ot-pc-desc {
  font-size: 14px;
}

/* Category Header Text*/
#onetrust-pc-sdk .ot-cat-header {
  font-size: 14px;
  font-weight: 600;
  line-height: 20px;
  margin: 0px !important
}


#onetrust-pc-sdk .ot-accordion-layout.ot-checkbox-consent .ot-acc-hdr .ot-cat-header {
  margin: none !important;
}

/* Category Header Position */
#onetrust-pc-sdk .ot-accordion-layout .ot-cat-header {
  min-height: initial;
}

/* Category Description */
#onetrust-pc-sdk .ot-acc-grpcntr.ot-acc-txt {
  background: none !important;
  padding: 0px 12px 12px 12px;
}

#onetrust-pc-sdk .ot-cat-item p:last-of-type {
  padding-top: 0px !important;
}

/* Hide Vendor Description */
#onetrust-pc-sdk .ot-subgrp-cntr {
  display: none;
}

/* Button Div */
#onetrust-pc-sdk .ot-btn-container {
  text-align: right;
  background: #F0F4F6;
  padding: 0px 24px 12px 0px;
  margin: 0px;
}

/* Save / Confirm choices button */
#onetrust-consent-sdk .save-preference-btn-handler {
  border-radius: 4px;
  font-size: 1em !important;
  font-weight: 500 !important;
  min-width: 116px !important;
}

#onetrust-pc-sdk .ot-pc-footer {
    height: auto !important;
}

/* Hide Footer Logo */
#onetrust-pc-sdk .ot-pc-footer-logo {
  display: none !important;
}

/* Toggle Button before */
#onetrust-pc-sdk .ot-tgl input:checked+.ot-switch .ot-switch-nob:before {
  background-color: #FFFFFF;
}

/* Toggle background after */
#onetrust-pc-sdk .ot-tgl input:checked+.ot-switch .ot-switch-nob {
  border: none !important;
  background: #0077C5;
}

#onetrust-pc-sdk .ot-tgl input:focus+.ot-switch .ot-switch-nob {
  outline-style: none !important;
}
#onetrust-pc-sdk .ot-tgl input:focus-visible+.ot-switch .ot-switch-nob {
      outline: 2px black solid !important;
      outline-offset: 2px !important;
}

#onetrust-consent-sdk #onetrust-pc-sdk .ot-tgl input:focus+.ot-switch,
.ot-switch .ot-switch-nob,
.ot-switch .ot-switch-nob:before,
#onetrust-pc-sdk .ot-checkbox input[type="checkbox"]:focus+label::before,
#onetrust-pc-sdk .ot-chkbox input[type="checkbox"]:focus+label::before {
  outline: none !important
}

/* #onetrust-consent-sdk #onetrust-pc-sdk .ot-tgl input:focus-visible+.ot-switch, */
#onetrust-pc-sdk .ot-checkbox input[type="checkbox"]:focus-visible+label::before,
#onetrust-pc-sdk .ot-chkbox input[type="checkbox"]:focus-visible+label::before {
      outline: 2px black solid !important;
      outline-offset: 2px !important;
}

/* on page link */
.ot-sdk-show-settings:hover {
  cursor: pointer;
}

/* Cookie policy link */
#onetrust-pc-sdk #ot-pc-desc a {
  display: inline;
  color: #0077c5;
}

/* Cookie policy link - remove border */
#onetrust-consent-sdk #onetrust-pc-sdk *:focus,
#onetrust-consent-sdk #onetrust-pc-sdk .ot-vlst-cntr>a:focus {
  outline: none !important;
}

#onetrust-consent-sdk #onetrust-pc-sdk *:focus-visible,
#onetrust-consent-sdk #onetrust-pc-sdk .ot-vlst-cntr>a:focus-visible {
   outline: 2px black solid !important;
      outline-offset: 2px !important;
}



/* Hide first toggle switch by class ot-switch-nob */
.ot-sdk-row>.ot-accordion-layout:first-of-type .ot-switch-nob {
  display: none;
}


/* Hide the original label text */
.ot-sdk-row>.ot-accordion-layout:first-of-type .ot-label-txt {
  position: relative !important;
  color: transparent;
  font-size: 0;
  display: inline-block !important;
}

/* Insert "Always Allow" text */
.ot-sdk-row>.ot-accordion-layout:first-of-type .ot-label-txt::after {
  content: "Always Active";
  display: inline-block;
  position: absolute;
  font-size: 14px;
  font-weight: 600;
  line-height: 16px;
  color: #0077C5;
  width: max-content;
  transform: translate(-75%, -50%);
}


/* insert labels for toggles */
#ot-pc-content>section>div:nth-child(3)>div.ot-acc-hdr>div.ot-tgl>input:checked+.ot-switch::before {
  content: "Yes";
  position: absolute;
  left: -34px;
  font-size: 14px;
  top: 4px;
  color: #0077C5;
}

#ot-pc-content>section>div:nth-child(3)>div.ot-acc-hdr>div.ot-tgl>input:not(:checked)+.ot-switch::before {
  content: "No";
  position: absolute;
  left: -34px;
  font-size: 14px;
  top: 4px;
  color: #BABEC5;
  display: inline-block;
}

/******************* OVERRIDES *********************/

/* Hide Essential & Advertising Headers */
.ot-cat-header {
  visibility: hidden !important;
  font-size: 0px !important;
  /* position: relative; */
}

/* Overrite Essential Header */
#ot-pc-content>section>div:nth-child(2)>div.ot-acc-hdr.ot-always-active-group>h4.ot-cat-header::after {
  content: "Essential, Enhanced Experience & Product Improvement";
  font-size: 14px;
  font-weight: 600;
  line-height: 20px;
  visibility: visible;
  position: absolute;
}

/* Overrite Advertising Header */
#ot-pc-content>section>div:nth-child(3)>div.ot-acc-hdr>h4.ot-cat-header::after {
  content: "Third-Party Advertisement";
  font-size: 14px;
  font-weight: 600;
  line-height: 20px;
  visibility: visible;
  position: absolute;
}

/* Hide original Essential & Advetising descriptions */
.ot-category-desc {
  visibility: hidden !important;
  font-size: 0px !important;
  margin-top: 0px !important;
}

/* Overrite Essential description */
/* #ot-pc-content>section>div:nth-child(2)>div.ot-acc-grpcntr.ot-acc-txt*/
#ot-pc-content>section>div:nth-child(2)>div.ot-acc-grpcntr.ot-acc-txt::after {
  content: "These first-party cookies are set by Intuit or one of our service providers; you cannot turn these off. These cookies enable the site to function as intended, including: basic functionality (for example, your ability to log into your Intuit account or add items to your cart for purchase); remember your preferences (for example, your preferred language or login credentials); provide you personalized content when viewing our site; and, allow us to evaluate your use and navigation of the site to fix bugs and improve the overall experience for you and others. A single cookie may be used for one or all of these purposes.";
  clear: both;
  float: left;
  visibility: visible;
  position: relative;
  font-size: 13px;
  line-height: 18px;
  color: #5F686E;
  margin: 0px 24px 12px 8px;
}

/* Overrite Advertising description */
/* #ot-pc-content>section>div:nth-child(3)>div.ot-acc-grpcntr.ot-acc-txt*/
#ot-pc-content>section>div:nth-child(3)>div.ot-acc-grpcntr.ot-acc-txt::after {
  content: "We leverage advertising trackers across our sites to improve our marketing and advertising activities. These trackers may share some limited personal information with third-party platforms where we may display advertisements or run marketing campaigns. You may choose to turn these trackers off. You will still see Intuit advertisements when you opt-out, but these ads may not be tailored to your interests. This preference applies to your experience on our .intuit sites, once you create or login to your Intuit account, you may be prompted to choose again.";
  clear: both;
  float: left;
  visibility: visible;
  position: relative;
  font-size: 13px;
  line-height: 18px;
  color: #5F686E;
  margin: 0px 24px 12px 8px;
}

/******************* END OVERRIDES *********************/

#onetrust-pc-sdk .ot-btn-container.ot-button-order-container.ot-stack-buttons .save-preference-btn-handler {
  width: auto !important
}
#onetrust-pc-sdk .ot-btn-container.ot-button-order-container.ot-stack-buttons {
